INSERT INTO _migration_623_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_bece_intsci_s3_027', 'topic_bece_science_electricity', 'subj_bece_science', 'exam_bece', NULL, NULL, 'Kofi wants to connect a simple circuit to light a bulb for his study table.', 'structured', NULL, NULL, '(a) (i) The battery provides the electrical energy (voltage) that pushes current round the circuit (1). (ii) The switch opens or closes the circuit to turn the current off or on (1). (b) Copper wire; copper is a very good conductor of electricity (1). (c) If a fault makes the current too large, the thin fuse wire melts and breaks the circuit (1); this protects the lamp and prevents the cable from overheating and causing a fire (1).', '(a) (i) The battery provides the electrical energy (voltage) that pushes current round the circuit (1). (ii) The switch opens or closes the circuit to turn the current off or on (1). (b) Copper wire; copper is a very good conductor of electricity (1). (c) If a fault makes the current too large, the thin fuse wire melts and breaks the circuit (1); this protects the lamp and prevents the cable from overheating and causing a fire (1).', 'medium', '5', '5', NULL, NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_028', 'topic_bece_science_machines', 'subj_bece_science', 'exam_bece', NULL, NULL, 'A wheelbarrow carries a load of sand placed between the wheel (the pivot) and the gardener’s hands (the effort). Which class of lever is the wheelbarrow?', 'multiple_choice', NULL, '["A. Second-class lever, because the load is between the pivot and the effort","B. First-class lever, because the pivot is between the load and the effort","C. Third-class lever, because the effort is between the pivot and the load","D. It is not a lever at all but a pulley"]', 'A', 'In a second-class lever the load lies between the fulcrum and the effort, which gives a large mechanical advantage — a small effort lifts a heavy load. The wheel is the fulcrum, the sand is the load and the hands supply the effort. (First class has the pivot in the middle, like a see-saw; third class has the effort in the middle, like tongs or a fishing rod.) Therefore the correct answer is A: Second-class lever, because the load is between the pivot and the effort.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Classify', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_029', 'topic_bece_science_machines', 'subj_bece_science', 'exam_bece', NULL, NULL, 'Porters push a heavy drum up a long plank onto a lorry instead of lifting it vertically. Which statement correctly explains why the plank (an inclined plane) helps?', 'multiple_choice', NULL, '["A. The plank reduces the weight of the drum","B. A smaller effort is needed because the load moves over a longer distance","C. The total work done against gravity is reduced","D. The plank removes friction completely"]', 'B', 'An inclined plane lets the porters use a smaller force spread over a longer distance. The work done against gravity (weight × vertical height) is the same either way; only the effort needed at each moment is smaller. (The drum’s weight is unchanged, and a rough plank can even add friction — it is never removed completely.) Therefore the correct answer is B: A smaller effort is needed because the load moves over a longer distance.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_030', 'topic_bece_science_machines', 'subj_bece_science', 'exam_bece', NULL, NULL, 'State two ways of reducing friction between the moving parts of a machine.', 'short_answer', NULL, NULL, 'Any two of: lubricating the parts with oil or grease; using ball bearings or rollers; polishing or smoothing the rubbing surfaces; separating the surfaces with a cushion of air.', 'Friction between moving parts wastes energy and wears the parts out. It can be reduced by lubricating with oil or grease, which keeps the surfaces slightly apart; by fitting ball bearings or rollers so the parts roll instead of slide; by polishing the surfaces to make them smoother; or by separating them with a cushion of air. Any two of these methods earn the marks.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_031', 'topic_bece_science_machines', 'subj_bece_science', 'exam_bece', NULL, NULL, 'A pupil pushes a box along the floor with a steady force of 50 N and moves it 4 m in the direction of the force. Calculate the work done on the box.', 'calculation', NULL, NULL, '200 J', 'Work done = force × distance moved in the direction of the force = 50 N × 4 m = 200 J. Answer: the work done on the box is 200 J.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_032', 'topic_bece_science_machines', 'subj_bece_science', 'exam_bece', NULL, NULL, 'Abena uses a long spanner to loosen a tight nut on her bicycle.', 'structured', NULL, NULL, '(a) The pivot (fulcrum), the effort and the load (all three needed for the mark). (b) First class: a pair of scissors, pliers or a see-saw — the pivot is between the load and the effort (1). Third class: tongs, a fishing rod or a broom — the effort is between the pivot and the load (1). (c) The turning effect (moment) of a force equals the force × the perpendicular distance from the pivot (1); a longer spanner gives a greater distance, so the same effort produces a larger turning effect on the nut (1).', '(a) The pivot (fulcrum), the effort and the load (all three needed for the mark). (b) First class: a pair of scissors, pliers or a see-saw — the pivot is between the load and the effort (1). Third class: tongs, a fishing rod or a broom — the effort is between the pivot and the load (1). (c) The turning effect (moment) of a force equals the force × the perpendicular distance from the pivot (1); a longer spanner gives a greater distance, so the same effort produces a larger turning effect on the nut (1).', 'medium', '5', '5', NULL, NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT INTO _migration_623_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_bece_intsci_s3_027_a', 'q_bece_intsci_s3_027', 'a', 'State the function of each of the following in the circuit: (i) the battery, (ii) the switch.', '2', '(i) The battery provides the electrical energy (voltage) that pushes current round the circuit (1). (ii) The switch opens or closes the circuit to turn the current off or on (1).', '1'),
('sqp_q_bece_intsci_s3_027_b', 'q_bece_intsci_s3_027', 'b', 'Name the material used to join the components, and state the property that makes it suitable.', '1', 'Copper wire; copper is a very good conductor of electricity (1).', '2'),
('sqp_q_bece_intsci_s3_027_c', 'q_bece_intsci_s3_027', 'c', 'Explain why a fuse is included in the plug of the table lamp.', '2', 'If a fault makes the current too large, the thin fuse wire melts and breaks the circuit (1); this protects the lamp and prevents the cable from overheating and causing a fire (1).', '3'),
('sqp_q_bece_intsci_s3_032_a', 'q_bece_intsci_s3_032', 'a', 'Name the three main parts of any lever.', '1', 'The pivot (fulcrum), the effort and the load (all three needed for the mark).', '1'),
('sqp_q_bece_intsci_s3_032_b', 'q_bece_intsci_s3_032', 'b', 'Give one example each of a first-class and a third-class lever used at home.', '2', 'First class: a pair of scissors, pliers or a see-saw — the pivot is between the load and the effort (1). Third class: tongs, a fishing rod or a broom — the effort is between the pivot and the load (1).', '2'),
('sqp_q_bece_intsci_s3_032_c', 'q_bece_intsci_s3_032', 'c', 'Explain why the long spanner loosens the nut more easily than a short one.', '2', 'The turning effect (moment) of a force equals the force × the perpendicular distance from the pivot (1); a longer spanner gives a greater distance, so the same effort produces a larger turning effect on the nut (1).', '3');
INSERT INTO _migration_623_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_623_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_623_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'bece-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_623_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_623_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_623_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'bece-int-science-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/common-core-programme-ccp/', 0, 1 FROM _migration_623_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_623_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_623_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_623_expected e ON e.id = r.question_id WHERE r.batch_id IS 'bece-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_623_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_623_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 6 THEN 1 ELSE 0 END;
